Definition pf_ctx (m m1 : mem) (sp : word) (SV : list cell) (B E L lo shi : Z) (p0 : Z) (bs : list byte)
    (lowc tl tmp : list cell) (pv : Z) (nmc vlc : list cell) (bsz : Z) (bb : list byte) (ecs : list cell) (g : bool) : Prop :=
  rw_cells bsegs m1 (bv_unsigned sp + -192) lowc
  /\ rw_cells bsegs m1 (bv_unsigned sp + -136) tl
  /\ rw_cells bsegs m1 (bv_unsigned sp + -128) tmp
  /\ rw_cells bsegs m1 (bv_unsigned sp + -104) SV
  /\ rw_cells bsegs m1 (bv_unsigned sp + 144) [C8 (wz pv)]
  /\ rw_cells bsegs m1 (bv_unsigned sp + 168) nmc
  /\ rw_cells bsegs m1 (bv_unsigned sp + 152) vlc
  /\ rw_cells bsegs m1 B [C8 (wz bsz); CB 4096 bb]
  /\ rw_cells bsegs m1 E ecs
  /\ bytes_at bsegs m1 p0 bs /\ L = p0 + Z.of_nat (length bs) /\ APfTab m1
  /\ AHttpCat m1 g
  /\ stk bsegs m1 lo (bv_unsigned sp + -192)
  /\ munch (pf_W lo sp B E) m m1 /\ wmono bsegs m m1 /\ mem_inv bsegs m1
  /\ pf_side m B E p0 (Z.of_nat (length bs)) lo shi.

(* [comment removed for export] *)
Definition pf_lows (x0 x8 x16 x24 x32 : word) (E : Z) : list cell :=
  [C8 x0; C8 x8; C8 x16; C8 x24; C8 x32; C8 (shw (E + 16)); C8 (wz (E + 16))].

Lemma pf_pwin : forall sp B E lo shi p0 bs E0, pf_pure sp B E lo shi p0 bs E0 -> Forall pwin (pf_W lo sp B E).
Proof.
  intros sp B E lo shi p0 bs E0 (_ & _ & LO & CEIL & APW & APE & EAL & APB & BAL & _).
  unfold pf_W, PF_STACK, AASSIGN_STACK, AINTRIN_STACK in *. repeat apply Forall_cons; [| | | | | apply Forall_nil].
  - apply pwin_stack. exact CEIL.
  - apply pwin_stack. clear - CEIL LO. lia.
  - eapply pwin_aapp; [exact APB| clear; lia| clear; lia].
  - eapply pwin_aapp; [exact APE| clear; lia| clear; lia].
  - exact pwin_httpcat.
Qed.

Lemma pf_fail_exit : forall e loc,
  In e [HE_NEED_MORE; HE_HEADER_LIMIT; HE_BAD_LINE_ENDING; HE_BAD_FIELD; HE_BAD_VALUE] ->
  Z.even loc = true -> 4 <= loc -> loc + 1 < 2^64 -> pf_fail (EC_http_loc e loc).
Proof.
  intros e loc HE EV L1 L2.
  assert (NZ : e <> 0 /\ 0 <= e < 2^32) by (cbn in HE; unfold HE_NEED_MORE, HE_HEADER_LIMIT, HE_BAD_LINE_ENDING, HE_BAD_FIELD, HE_BAD_VALUE in HE; lia).
  unfold pf_fail, EC_http_loc, ec_make_loc, ec_failed, ec_ok. cbn [ec_val ec_cat ec_flags].
  replace (e =? 0) with false by (symmetry; apply Z.eqb_neq; lia).
  unfold AG_HTTP_CAT. repeat split; try assumption; try lia. apply odd_loc1. exact EV.
Qed.
