(* [comment removed for export] *)
Definition pf_exitA_stmt (pc e loc : Z) : Prop :=
  forall rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s1x s2x s3x s4x s5x s6x s7x s8x s10x s11x
         s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (B E L lo shi : Z) (p0 : Z) (bs : list byte) (E0 : ecv)
    (lowc tl : list cell) (pv : Z) (nmc vlc : list cell) (bsz : Z) (bb : list byte) (e1 e2 e3 : word) (g : bool) (j24 : list byte),
  pf_ctx m m1 sp (pch_saved s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra) B E L lo shi p0 bs
         lowc tl [CB 24 j24] pv nmc vlc bsz bb [C8 e1; C8 e2; C8 e3] g ->
  pf_pure sp B E lo shi p0 bs E0 -> 0 <= bsz <= 4096 -> 0 <= pv < 2^64 ->
  cells_size lowc = 56%nat -> cells_size tl = 8%nat -> cells_size nmc = 16%nat -> cells_size vlc = 16%nat ->
  In e [HE_NEED_MORE; HE_HEADER_LIMIT; HE_BAD_LINE_ENDING; HE_BAD_FIELD; HE_BAD_VALUE] ->
  evt bsegs (pf_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc B E lo shi p0 bs E0 m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -192)) gp tp t0 t1 t2 (wz E) s1x a0 a1 a2 a3 a4 a5 a6 a7
              s2x s3x s4x s5x s6x s7x s8x (wz 2147450880) s10x s11x t3 t4 t5 t6)
        F (Z_to_bv 64 pc) fc None m1 (seg_rom bsegs)).

(* [comment removed for export] *)
Definition pf_exitS_stmt (pc e loc : Z) : Prop :=
  forall rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s1x s2x s3x s4x s5x s6x s7x s8x s10x s11x
         s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (B E L lo shi : Z) (p0 : Z) (bs : list byte) (E0 : ecv)
    (x0 x8 x16 x24 x32 : word) (tl : list cell) (pv : Z) (nmc vlc : list cell) (bsz : Z) (bb : list byte) (e1 e2 e3 : word) (g : bool) (j24 : list byte),
  pf_ctx m m1 sp (pch_saved s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra) B E L lo shi p0 bs
         (pf_lows x0 x8 x16 x24 x32 E) tl [CB 24 j24] pv nmc vlc bsz bb [C8 e1; C8 e2; C8 e3] g ->
  pf_pure sp B E lo shi p0 bs E0 -> 0 <= bsz <= 4096 -> 0 <= pv < 2^64 ->
  cells_size tl = 8%nat -> cells_size nmc = 16%nat -> cells_size vlc = 16%nat ->
  In e [HE_NEED_MORE; HE_HEADER_LIMIT; HE_BAD_LINE_ENDING; HE_BAD_FIELD; HE_BAD_VALUE] ->
  evt bsegs (pf_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc B E lo shi p0 bs E0 m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -192)) gp tp t0 t1 t2 (wz E) s1x a0 a1 a2 a3 a4 a5 a6 a7
              s2x s3x s4x s5x s6x s7x s8x (wz 2147450880) s10x s11x t3 t4 t5 t6)
        F (Z_to_bv 64 pc) fc None m1 (seg_rom bsegs)).
End CTXDEF.

(* [comment removed for export] *)
Ltac pf_finish p' E' g' n1 n2 v1 v2 bsz bb :=
  apply evt_done; unfold pf_post, aoPP, aoNM, aoVL, APfTab, APF_TABPTR, AL_TAB_IS_TOKEN_LIT;
  do 16 eexists; exists p', E', g', n1, n2, v1, v2, bsz, bb;
  split; [reflexivity|]; repeat match goal with |- _ /\ _ => split end; try assumption; try lia.

(* [comment removed for export] *)
Ltac pf_rectx SIDE :=
  unfold pf_ctx, pf_W, pf_lows, pch_saved, AG_HTTP_CAT, APfTab, APF_TABPTR, AL_TAB_IS_TOKEN_LIT, shw, wz;
  repeat (split; [first [fast_eassumption | reflexivity] |]); exact SIDE.

(* [comment removed for export] *)
Ltac open_pf CTX PURE :=
  destruct CTX as (FRlo & TL & TMP & FRhi & PPC & NMC & VLC & BFC & EC & WIN & LL & TB & HC & ST & MU & WM & MI & SIDE);
  pose proof (pf_pwin _ _ _ _ _ _ _ _ PURE) as FW;
  destruct PURE as (EOK & EF0 & LO & CEIL & APW & APE & EAL & APB & BAL & DWE & DWB & DBE & SPAL & SHI);
  let SHI64 := fresh "SHI64" in
  lazymatch type of SHI with ?x + 184 <= ?y => assert (SHI64 : x + 64 <= y) by (clear - SHI; lia) end;
  pose proof (ex_bnd_intro _ _ _ _ _ LO CEIL SHI64 APE) as BND;
  pose proof BND as BNDv; unfold ex_bnd in BNDv; destruct BNDv as (_ & _ & _ & SPR & EB1 & EB2 & EB3 & EB4 & AF1);
  pose proof (stack0_bounds _ _ _ (pside2_stack0 _ _ _ _ _ SIDE)) as [SKB1 SKB2];
  pose proof (aapp_bounds _ 4104 APB ltac:(lia)) as (BB1 & BB2 & BB3 & BB4 & BB5);
  pose proof (bytes_at_bound _ _ _ _ WIN) as WB;
  pose proof (aapp_bounds _ _ APW ltac:(lia)) as (WB1 & WB2 & WB3 & WB4 & WB5);
  clear BB5 WB5; hydeL DWE; hydeL DWB; hydeL DBE; hydeL EAL; hydeL BAL; hydeL SPAL;
  unfold pf_W, pf_lows, pch_saved, PF_STACK, AASSIGN_STACK, AINTRIN_STACK, AG_HTTP_CAT, AAPP_HI, AIMG_TOP, APfTab, APF_TABPTR, AL_TAB_IS_TOKEN_LIT in *;
  unfold wz in *.

(* [comment removed for export] *)
Ltac pf_exit_tail SIDE FW BND LO CEIL APB APW APE DBE DWE PPC NMC VLC BFC WIN TB SZL SZT SZN SZV E e loc m sp lo pv bsz bb HE :=
  st1; steps_to 0xd4c7c%Z;
  (* [comment removed for export] *)
  lazymatch goal with FRl : rw_cells _ _ (bv_unsigned sp + -192) _ |- _ =>
    let j := fresh "jlo" in let F2 := fresh "FRlo" in
    destruct (rw_cells_forget _ _ _ _ FRl) as [j F2]; clear FRl;
    cbn [cells_size csize Nat.add length] in F2; try rewrite SZL in F2
  end;
  lazymatch goal with TLc : rw_cells _ _ (bv_unsigned sp + -136) _ |- _ =>
    let j := fresh "jtl" in let F2 := fresh "TL" in
    destruct (rw_cells_forget _ _ _ _ TLc) as [j F2]; clear TLc;
    cbn [cells_size csize Nat.add length] in F2; try rewrite SZT in F2
  end;
  lazymatch goal with
  | FRlo : rw_cells _ _ (bv_unsigned sp + -192) _, TL : rw_cells _ _ (bv_unsigned sp + -136) _,
    TMPa : rw_cells _ _ (bv_unsigned sp + -128) [C8 _; C8 _],
    TMPb : rw_cells _ _ (bv_unsigned sp + -112) [C8 _], FRhi : rw_cells _ _ (bv_unsigned sp + -104) _,
    ST3 : stk _ _ _ (bv_unsigned sp + -192) |- _ =>
      join_frameA TMPa TMPb (bv_unsigned sp + -128); join_frameA TMPa FRhi (bv_unsigned sp + -128);
      join_frameA TL TMPa (bv_unsigned sp + -136); join_frameA FRlo TL (bv_unsigned sp + -192);
      step; release_frame FRlo ST3 (bv_unsigned sp)
  end;
  step;
  assign_loc_close SIDE FW BND E e loc m;
  (* [comment removed for export] *)
  unpark PPC; unpark NMC; unpark VLC; unpark BFC; unpark WIN; unpark TB;
  lazymatch goal with MUx : munch [(lo, bv_unsigned sp); (E, E + 24); (6684368, 6684368 + 64)]%Z ?m1 ?m4, WMx : wmono _ ?m1 ?m4 |- _ =>
    let K := fresh "FAR" in
    pose proof (pf_far_transport _ _ sp lo _ E _ _ pv _ _ bsz bb MUx WMx CEIL ltac:(clear - LO; lia) APB APW APE
                  ltac:(clear - DBE; unfold hideL in DBE; exact DBE) ltac:(clear - DWE; unfold hideL in DWE; exact DWE)
                  SZN SZV PPC NMC VLC BFC WIN TB) as K;
    clear PPC NMC VLC BFC WIN TB; destruct K as (PPC & NMC & VLC & BFC & WIN & TB)
  end;
  let n1 := fresh "n1" in let n2 := fresh "n2" in let v1 := fresh "v1" in let v2 := fresh "v2" in
  let NMC' := fresh "NMC'" in let VLC' := fresh "VLC'" in
  destruct (cells16_words _ _ _ NMC SZN) as (n1 & n2 & NMC'); destruct (cells16_words _ _ _ VLC SZV) as (v1 & v2 & VLC');
  clear NMC VLC;
  pf_finish pv (EC_http_loc e loc) true n1 n2 v1 v2 bsz bb;
  right; apply pf_fail_exit; [exact HE | reflexivity | clear; lia | clear; lia].

(* [comment removed for export] *)
Ltac pf_exitA_script MEMCPY ASSIGNA e loc CHK :=
  unfold pf_exitA_stmt;
  intros rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s1x s2x s3x s4x s5x s6x s7x s8x s10x s11x
         s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v t3 t4 t5 t6
         F fc m m1 B E L lo shi p0 bs E0 lowc tl pv nmc vlc bsz bb e1 e2 e3 g j24;
  intros CTX PURE BSZ PV SZL SZT SZN SZV HE;
  destruct CTX as (FRlo & TL & TMP & FRhi & PPC & NMC & VLC & BFC & EC & WIN & LL & TB & HC & ST & MU & WM & MI & SIDE);
  pose proof (pf_pwin _ _ _ _ _ _ _ _ PURE) as FW;
  destruct PURE as (EOK & EF0 & LO & CEIL & APW & APE & EAL & APB & BAL & DWE & DWB & DBE & SPAL & SHI);
  let SHI64 := fresh "SHI64" in
  lazymatch type of SHI with ?x + 184 <= ?y => assert (SHI64 : x + 64 <= y) by (clear - SHI; lia) end;
  pose proof (ex_bnd_intro _ _ _ _ _ LO CEIL SHI64 APE) as BND;
  pose proof BND as BNDv; unfold ex_bnd in BNDv; destruct BNDv as (_ & _ & _ & SPR & EB1 & EB2 & EB3 & EB4 & AF1);
  pose proof (stack0_bounds _ _ _ (pside2_stack0 _ _ _ _ _ SIDE)) as [SKB1 SKB2];
  pose proof (aapp_bounds _ 4104 APB ltac:(lia)) as (BB1 & BB2 & BB3 & BB4 & BB5);
  pose proof (bytes_at_bound _ _ _ _ WIN) as WB;
  pose proof (aapp_bounds _ _ APW ltac:(lia)) as (WB1 & WB2 & WB3 & WB4 & WB5);
  clear BB5 WB5; hydeL DWE; hydeL DWB; hydeL DBE; hydeL EAL; hydeL BAL; hydeL SPAL;
  unfold pf_W, pf_lows, pch_saved, PF_STACK, AASSIGN_STACK, AINTRIN_STACK, AG_HTTP_CAT, AAPP_HI, AIMG_TOP, APfTab, APF_TABPTR, AL_TAB_IS_TOKEN_LIT in *;
  unfold wz in *;
  assert (D8 : (bv_unsigned sp + -128) mod 8 = 0) by (clear - SPAL; unfold hideL in SPAL; Z.div_mod_to_equations; lia);
  hydeL D8; unfold shw in *;
  pose proof (munch_refl [(lo, bv_unsigned sp); (E, E + 24); (6684368, 6684368 + 64)]%Z m1) as MUx;
  pose proof (wmono_refl bsegs m1) as WMx;
  park PPC; park NMC; park VLC; park BFC; park WIN; park TB;
  destruct (rw_cells_forget _ _ _ _ EC) as [ej EC2]; cbn [cells_size csize Nat.add] in EC2; clear EC;
  assign_loc_core MEMCPY ASSIGNA SIDE MU WM FW HC TMP EC2 ST MI APE D8 BND (bv_unsigned sp + -128) E e loc lo shi sp g j24 ej m;
  assign_loc_chk SIDE FW EAL E m CHK;
  pf_exit_tail SIDE FW BND LO CEIL APB APW APE DBE DWE PPC NMC VLC BFC WIN TB SZL SZT SZN SZV E e loc m sp lo pv bsz bb HE.

Ltac pf_exitS_script MEMCPY ASSIGNA e loc CHK NAV :=
  unfold pf_exitS_stmt;
  intros rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s1x s2x s3x s4x s5x s6x s7x s8x s10x s11x
